param([switch]$ManageApi,[switch]$DebugPause)
$ErrorActionPreference='Stop';$repo=Split-Path $PSScriptRoot -Parent
if(!$ManageApi){throw 'Use -ManageApi; this demo uses only the dedicated Test database.'}
if(Get-NetTCPConnection -State Listen -LocalPort 5100 -ErrorAction SilentlyContinue){throw 'Port5100 occupied; stop owned debug hosts first.'}
$dir=Join-Path $repo '.local/m20-demo';New-Item -ItemType Directory -Force $dir|Out-Null
$keys=@('ASPNETCORE_ENVIRONMENT','DOTNET_ENVIRONMENT','ASPNETCORE_URLS','Runtime__Enabled','ConnectionStrings__ContentOS','Staff__Administrator__0','Customers__FixtureSigningKey','Workflows__WorkerEnabled','Knowledge__IndexWorkerEnabled','Factory__WorkerEnabled','Read__RetentionWorkerEnabled','Trends__RecheckWorkerEnabled','Media__WorkerEnabled','Watch__WorkerEnabled','Social__WorkerEnabled')
$prior=@{};foreach($k in $keys){$prior[$k]=[Environment]::GetEnvironmentVariable($k)};$owned=@()
try{
$secretBytes=New-Object byte[] 32;$rng=[Security.Cryptography.RandomNumberGenerator]::Create();$rng.GetBytes($secretBytes);$rng.Dispose();$env:Customers__FixtureSigningKey=[Convert]::ToBase64String($secretBytes);[Array]::Clear($secretBytes,0,$secretBytes.Length)
$project="<Project Sdk=""Microsoft.NET.Sdk""><PropertyGroup><OutputType>Exe</OutputType><TargetFramework>net10.0</TargetFramework><ImplicitUsings>enable</ImplicitUsings><Nullable>enable</Nullable></PropertyGroup><ItemGroup><FrameworkReference Include=""Microsoft.AspNetCore.App""/><ProjectReference Include=""$repo/src/ContentOS.Infrastructure/ContentOS.Infrastructure.csproj""/><ProjectReference Include=""$repo/src/ContentOS.Integrations/ContentOS.Integrations.csproj""/><Compile Include=""$repo/scripts/fixtures/CustomerDemo.cs"" Link=""Program.cs""/><Compile Include=""$repo/tests/ContentOS.Foundation.Tests/CustomerTestFixture.cs"" Link=""CustomerTestFixture.cs""/></ItemGroup></Project>"
[IO.File]::WriteAllText((Join-Path $dir 'Demo.csproj'),$project)
& dotnet build (Join-Path $dir 'Demo.csproj') --disable-build-servers -m:1 -p:UseSharedCompilation=false
if($LASTEXITCODE -ne 0){throw 'M20 fixture build failed.'}
& dotnet (Join-Path $dir 'bin/Debug/net10.0/Demo.dll') $dir
if($LASTEXITCODE -ne 0){throw 'M20 fixture setup failed.'}
$f=Get-Content (Join-Path $dir 'fixture.json') -Raw|ConvertFrom-Json
$env:ASPNETCORE_ENVIRONMENT='Development';$env:DOTNET_ENVIRONMENT='Development';$env:Runtime__Enabled='true';$env:ASPNETCORE_URLS='http://localhost:5100';$env:ConnectionStrings__ContentOS='Server=localhost;Database=GeetaStudio_M1Tests;Integrated Security=True;Encrypt=True;TrustServerCertificate=True;';$env:Staff__Administrator__0=[Security.Principal.WindowsIdentity]::GetCurrent().Name
foreach($key in $keys|Where-Object {$_ -like '*WorkerEnabled'}){[Environment]::SetEnvironmentVariable($key,'false')}
function Start-OwnedApi($number){$p=Start-Process -FilePath (Join-Path $repo 'src/GeetaStudio.Api/bin/Debug/net10.0/GeetaStudio.Api.exe') -WorkingDirectory (Join-Path $repo 'src/GeetaStudio.Api') -WindowStyle Hidden -PassThru -RedirectStandardOutput (Join-Path $dir "api-$number.out") -RedirectStandardError (Join-Path $dir "api-$number.err");$script:owned+=$p;for($i=0;$i -lt 60;$i++){if($p.HasExited){throw 'Owned API exited'};try{Invoke-WebRequest 'http://localhost:5100/health/ready' -UseBasicParsing|Out-Null;return $p}catch{Start-Sleep -Milliseconds 500}};throw 'API startup timeout'}
function Post-Private($url,$body){Invoke-RestMethod $url -Method Post -ContentType 'application/json' -Headers @{'X-ContentOS-Staff'='1'} -Body ($body|ConvertTo-Json -Depth 14) -UseDefaultCredentials}
function Refresh-TestDelivery($body){$body.sentAtUnix=[DateTimeOffset]::UtcNow.ToUnixTimeSeconds();$mac=New-Object Security.Cryptography.HMACSHA256;$mac.Key=[Text.Encoding]::UTF8.GetBytes($env:Customers__FixtureSigningKey);try{$body.signature=([BitConverter]::ToString($mac.ComputeHash([Text.Encoding]::UTF8.GetBytes($body.sentAtUnix.ToString()+'.'+$body.payload)))).Replace('-','')}finally{$mac.Dispose()};return $body}
$api=Start-OwnedApi 1;$path="http://localhost:5100/api/v1/customer/tenants/$($f.tenant)";$admin="http://localhost:5100/api/v1/customer-admin/tenants/$($f.tenant)";$analytics="http://localhost:5100/api/v1/analytics/tenants/$($f.tenant)/universes/$($f.universe)"
$page=Invoke-WebRequest 'http://localhost:5100/account' -UseDefaultCredentials -UseBasicParsing;if($page.StatusCode -ne 200 -or $page.Headers['Cache-Control'] -ne 'no-store'){throw 'Private account page unavailable'}
$staffPage=Invoke-WebRequest 'http://localhost:5100/staff/customers' -UseDefaultCredentials -UseBasicParsing;if($staffPage.StatusCode -ne 200){throw 'Private administrator page unavailable'}
if($DebugPause){Write-Host "M20 API process $($api.Id). Attach Geeta Studio: M20 attach Api. Open /account; workspace $($f.tenant).";Read-Host 'Inspect ledger/linking/payment fences; press Enter to finish checks and cleanup'}
foreach($file in @('paid.json','subscription-paid.json')){$body=Refresh-TestDelivery (Get-Content (Join-Path $dir $file) -Raw|ConvertFrom-Json);$first=Post-Private "$admin/payment-events" $body;$second=Post-Private "$admin/payment-events" $body;if($first -ne $second){throw 'Duplicate payment event changed identity'}}
$wallet=Invoke-RestMethod "$path/wallet" -UseDefaultCredentials;if($wallet.available -ne 200 -or $wallet.reserved -ne 0){throw 'Verified purchase/failed-work balance differs'}
$entitlements=Invoke-RestMethod "$path/entitlements" -UseDefaultCredentials;if($entitlements.features -notcontains 'GeetaPlus' -or $entitlements.liveQualified){throw 'Fixture entitlement qualification differs'}
Post-Private "$analytics/capture-customer-payments" @{operationId=[guid]::NewGuid().ToString()}|Out-Null
foreach($file in @('refund.json','delayed-paid.json','cancel.json')){Post-Private "$admin/payment-events" (Refresh-TestDelivery (Get-Content (Join-Path $dir $file) -Raw|ConvertFrom-Json))|Out-Null}
Post-Private "$analytics/capture-customer-payments" @{operationId=[guid]::NewGuid().ToString()}|Out-Null
$duplicate=Post-Private "$analytics/capture-customer-payments" @{operationId=[guid]::NewGuid().ToString()};if($duplicate.inserted -ne 0){throw 'Payment finance capture duplicated revenue/refund'}
$api|Stop-Process;$api.WaitForExit(10000)|Out-Null;$api=Start-OwnedApi 2
$wallet=Invoke-RestMethod "$path/wallet" -UseDefaultCredentials;if($wallet.available -ne 100 -or $wallet.reversed -ne 100 -or $wallet.reserved -ne 0){throw 'Refund/restart changed wallet'}
$orders=Invoke-RestMethod "$path/orders" -UseDefaultCredentials;$original=$orders|Where-Object id -eq $f.creditOrder;$newer=$orders|Where-Object id -eq $f.newProviderOrder;if($original.provider -ne 'payment.fixture.a.v1' -or $original.state -ne 'Refunded' -or $newer.provider -ne 'payment.fixture.b.v1'){throw 'Original/replacement payment bindings differ'}
$features=Invoke-RestMethod "$path/entitlements" -UseDefaultCredentials;if($features.features.Count -ne 0){throw 'Cancelled subscription resurrected'}
$progress=Invoke-RestMethod "$path/profiles/$($f.child)/progress" -UseDefaultCredentials;if($progress[0].position -ne 4){throw 'Consented progress did not survive restart'}
$isolated=$false;try{Invoke-RestMethod "$path/profiles/$($f.otherProfile)/progress" -UseDefaultCredentials|Out-Null}catch{if([int]$_.Exception.Response.StatusCode -eq 403){$isolated=$true}else{throw}};if(!$isolated){throw 'Other household leaked through API'}
$starts=[Uri]::EscapeDataString([DateTimeOffset]::UtcNow.AddDays(-1).ToString('o'));$ends=[Uri]::EscapeDataString([DateTimeOffset]::UtcNow.AddDays(1).ToString('o'));$report=Invoke-RestMethod "$analytics/report?currency=INR&startsUtc=$starts&endsUtc=$ends" -UseDefaultCredentials;if($report.recognizedNet -ne 10){throw 'Known signed fixture payment/refund net differs'}
$evidence=[ordered]@{verifiedDate=(Get-Date -Format 'yyyy-MM-dd');windowsAccountPage200=$true;privateNoStore=$true;windowsAdministratorPage200=$true;concurrentReservationsSucceeded=1;failedGenerationReleasedExactlyOnce=$true;duplicateSignedPaymentEvents=$true;outOfOrderRefundDoesNotResurrect=$true;originalPaymentProviderPreserved=$true;identityLinksPreserveInternalUser=$true;householdIsolation403=$true;consentedProgressAfterApiRestart=4;cancelledEntitlementsEmpty=$true;finalAvailableCustomerCredits=100;reversedCredits=100;fixtureRecognizedNetInr=10;financeReimportInserted=0;apiRestart=$true;paidExternalCalls=0;liveQualified=$false;childPersonalizationEnabled=$false;freshInteractiveF5Verified=$false}
$evidence|ConvertTo-Json -Depth 5|Set-Content (Join-Path $repo 'docs/milestones/evidence/M20-demo.json')
Write-Host 'M20 Windows concurrent spending, signed payment replay/refund/cancel, provider history, household isolation, progress, finance and API restart passed. All amounts are synthetic.'
}finally{foreach($p in $owned){if(!$p.HasExited){Stop-Process -Id $p.Id;$p.WaitForExit(10000)|Out-Null}};foreach($k in $keys){[Environment]::SetEnvironmentVariable($k,$prior[$k])}}
